import { db } from "@purplefish-ai/db/server";
import { inngest } from "@/server/inngest/client";
import {
  createInboundRoutingDispatchRule,
  createInboundTrunk,
  deleteInboundDispatchRule,
  deleteInboundTrunk,
  deleteOutboundTrunk,
} from "@/server/libs/agent-phone-numbers";

export const configureAgentPhoneNumber = inngest.createFunction(
  {
    id: "configure-agent-phone-number",
  },
  {
    event: "configure.agent-phone-number.triggered",
  },
  async ({ step, event }) => {
    const agentPhoneNumber = await step.run(
      "get-agent-phone-number",
      async () => {
        return await db.agentPhoneNumber.findUniqueOrThrow({
          where: {
            number: event.data.phoneNumber,
          },
        });
      },
    );

    return await step.run("configure-agent-with-livekit", async () => {
      if (agentPhoneNumber.sipInboundTrunkId) {
        await deleteInboundTrunk(agentPhoneNumber.id);
      }
      if (agentPhoneNumber.sipInboundDispatchRuleId) {
        await deleteInboundDispatchRule(agentPhoneNumber.id);
      }
      if (agentPhoneNumber.sipOutboundTrunkId) {
        await deleteOutboundTrunk(agentPhoneNumber.id);
      }
      // using legacy inbound trunk creation here
      // this trunk will be used both for inbound and outbound calls
      const trunk = await createInboundTrunk({
        number: agentPhoneNumber.number,
      });

      const dispatchRule = await createInboundRoutingDispatchRule({
        sipInboundTrunkId: trunk.sipTrunkId,
        number: agentPhoneNumber.number,
      });

      return await db.agentPhoneNumber.update({
        where: {
          id: agentPhoneNumber.id,
        },
        data: {
          sipInboundTrunkId: trunk.sipTrunkId,
          sipInboundDispatchRuleId: dispatchRule.sipDispatchRuleId,
          sipOutboundTrunkId: trunk.sipTrunkId,
        },
      });
    });
  },
);

