    );
    vi.mocked(createInboundTrunk).mockResolvedValue(mockTrunk as any);
    vi.mocked(createInboundRoutingDispatchRule).mockResolvedValue(
      mockDispatchRule as any
    );
    vi.mocked(db.agentPhoneNumber.update).mockResolvedValue({} as any);

    // Create test engine
    const testEngine = new InngestTestEngine({
      function: configureAgentPhoneNumber,
      transformCtx: (ctx) => ({
        ...ctx,
        event: {
          ...ctx.event,
          name: "configure.agent-phone-number.triggered",
          data: {
            phoneNumber: mockPhoneNumber,
          },
        },
      }),
    });

    // Execute the function
    await testEngine.execute();

    // Assertions - verify only existing trunk was deleted
    expect(deleteInboundTrunk).toHaveBeenCalledWith(mockAgentPhoneNumber.id);
    expect(deleteInboundDispatchRule).not.toHaveBeenCalled();
    expect(deleteOutboundTrunk).not.toHaveBeenCalled();
  });

  it("should test individual steps execution", async () => {
    const mockPhoneNumber = "+14155551234";
    const mockAgentPhoneNumber = {
      id: "agent-phone-123",
      number: mockPhoneNumber,
      sipInboundTrunkId: null,
      sipInboundDispatchRuleId: null,
      sipOutboundTrunkId: null,
    };

    const mockUpdateResult = {
      ...mockAgentPhoneNumber,
      sipInboundTrunkId: "trunk-456",
      sipInboundDispatchRuleId: "dispatch-789",
      sipOutboundTrunkId: "trunk-456",
    };

    // Setup mocks for the first step
    vi.mocked(db.agentPhoneNumber.findUniqueOrThrow).mockResolvedValue(
      mockAgentPhoneNumber as any
    );

    // Setup mocks for the second step (even though we're only testing the first step)
    vi.mocked(createInboundTrunk).mockResolvedValue({ sipTrunkId: "trunk-456" } as any);
    vi.mocked(createInboundRoutingDispatchRule).mockResolvedValue({ sipDispatchRuleId: "dispatch-789" } as any);
    vi.mocked(db.agentPhoneNumber.update).mockResolvedValue(mockUpdateResult as any);

    // Create test engine
    const testEngine = new InngestTestEngine({
      function: configureAgentPhoneNumber,
      transformCtx: (ctx) => ({
        ...ctx,
        event: {
          ...ctx.event,
          name: "configure.agent-phone-number.triggered",
          data: {
            phoneNumber: mockPhoneNumber,
          },
        },
      }),
    });

    // Test first step - get agent phone number
    const step1Result = await testEngine.executeStep({
      stepId: "get-agent-phone-number",
    });

    // Check that the step was registered and executed
    expect(step1Result.state["get-agent-phone-number"]).toBeDefined();

    // Verify the database call was made correctly
    expect(db.agentPhoneNumber.findUniqueOrThrow).toHaveBeenCalledWith({
      where: {
        number: mockPhoneNumber,
      },
    });
  });

  it("should throw error when phone number is not found", async () => {
    const mockPhoneNumber = "+14155551234";

    // Setup mock to throw error
    vi.mocked(db.agentPhoneNumber.findUniqueOrThrow).mockRejectedValue(
