export const createInboundTrunk = async (
  agentPhoneNumber: Pick<AgentPhoneNumber, "number">,
) => {
  const inboundSipClient = getInboundSipClient();
  const inboundTrunks = await inboundSipClient.listSipInboundTrunk();
  const inboundTrunk = inboundTrunks.find((inboundTrunk) =>
    inboundTrunk.numbers.includes(agentPhoneNumber.number),
  );
  if (inboundTrunk) {
    return inboundTrunk;
  }

