export const createInboundTrunk = async (
  agentPhoneNumber: Pick<AgentPhoneNumber, "number">,
) => {
  const inboundSipClient = getInboundSipClient();
  const inboundTrunks = await inboundSipClient.listSipInboundTrunk();
  const inboundTrunk = inboundTrunks.find((inboundTrunk) =>
    inboundTrunk.numbers.includes(agentPhoneNumber.number),
  );
  if (inboundTrunk) {
    return inboundTrunk;
  }
  const newInboundTrunk = await inboundSipClient.createSipInboundTrunk(
    `inbound-trunk-${agentPhoneNumber.number}`,
    [agentPhoneNumber.number],
  );
  return newInboundTrunk;
};
export const createInboundDispatchRule = async (
  agentPhoneNumber: AgentPhoneNumber,
) => {
  const sipInboundTrunkId = agentPhoneNumber.sipInboundTrunkId;
  if (!sipInboundTrunkId) {
    throw new Error("Agent phone number has no inbound trunk");
  }
  const inboundSipClient = getInboundSipClient();

